 if(argc<3)throw std::runtime_error("probe INPUT OUTPUT [point] [--sectors-only]");json cfg;{std::ifstream f(argv[1]);f>>cfg;}bool only=argc>4&&std::string(argv[4])=="--sectors-only";cfg["specialize_t"]=argc>3?argv[3]:"17";prime=cfg.at("prime");nmod_init(&mod,prime);nmod_mpoly_ctx_init(mc,2,ORD_LEX,prime);auto start=Clock::now();NativeFamily family(cfg);json out={{"FBI_rank",family.rank},{"sector_count",family.sectors.size()},{"masters",family.masters},{"sectors",json::array()},{"point",cfg["specialize_t"]},{"construction_seconds",seconds(start)}};
